package domain

import (
	"encoding/json"
	"fmt"
	"time"
)

// Workspace is a simulation workbench materialized from selected import
// batches. SourceJSON keeps the raw lineage `{"batchIds":[…]}` (see
// WorkspaceSource); the repo layer stores it verbatim in
// workspaces.source_json. Ids are uuid strings (NewID-style, generated by the
// materialization service); simulation entity ids inside the workspace come
// from global per-kind sequences (vd-, if-, ln-, cs-, run-, cp-<n>).
type Workspace struct {
	ID          string
	Name        string
	Description string
	Status      WorkspaceStatus
	SourceJSON  string // raw JSON lineage {"batchIds":[…]}; "" behaves as "{}"
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

// Source decodes the workspace lineage. An empty or "null" SourceJSON yields
// a zero WorkspaceSource (no batches).
func (w Workspace) Source() (WorkspaceSource, error) {
	return ParseWorkspaceSource(w.SourceJSON)
}

// WorkspaceSource is the typed lineage of a workspace: the import batches it
// was materialized from. JSON field names are pinned by PROJECT_BRIEF_P2 §3
// ("batchIds"), so this struct carries json tags and is the ONLY Phase 2
// domain struct serialized by other layers verbatim.
type WorkspaceSource struct {
	BatchIDs []string `json:"batchIds"`
}

// ParseWorkspaceSource decodes a workspaces.source_json value. Empty input,
// "{}" and "null" all yield a zero WorkspaceSource; a JSON value that is not
// an object (or an undecodable object) returns an error.
func ParseWorkspaceSource(s string) (WorkspaceSource, error) {
	if s == "" || s == "null" {
		return WorkspaceSource{}, nil
	}
	var src WorkspaceSource
	if err := json.Unmarshal([]byte(s), &src); err != nil {
		return WorkspaceSource{}, fmt.Errorf("domain: parse workspace source %q: %w", s, err)
	}
	return src, nil
}

// VirtualDevice is a simulated device inside a workspace. ResourceID keeps
// the lineage to the imported device resource ("" = NULL = manually created,
// no lineage). Code is unique within the workspace. GeoLat/GeoLng are the
// OPTIONAL geographic position (nil = no position) — presentation metadata
// only: they flow import → resource attributes → materialization → the
// topology payload, but are deliberately EXCLUDED from the canonical
// workspace state hash (moving a device on a map must never change the
// state hash, checks or diffs).
type VirtualDevice struct {
	ID          string
	WorkspaceID string
	ResourceID  string // "" = no lineage resource (SQL NULL)
	Code        string
	Name        string
	Status      EntityStatus
	GeoLat      *float64 // nil = no position (SQL NULL)
	GeoLng      *float64 // nil = no position (SQL NULL)
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

// SimInterface is a simulated interface of a VirtualDevice. The name is
// pinned to "SimInterface" (not "Interface") to avoid clashing with the
// standard library. IPv4Addr is a dotted quad in canonical form; the pair
// (IPv4Addr == "", IPv4Prefix == -1) means "unconfigured" (SQL NULLs). When
// the address is configured, IPv4Prefix is 0..32.
type SimInterface struct {
	ID          string
	WorkspaceID string
	DeviceID    string
	Name        string // e.g. "eth0"
	Status      EntityStatus
	IPv4Addr    string // "" = unconfigured (SQL NULL)
	IPv4Prefix  int    // -1 = SQL NULL; 0..32 when IPv4Addr is set
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

// SimLink connects two SimInterfaces (which must live on different devices).
// Label is free text (the circuit_code when the link was derived from a
// circuit resource); ResourceID keeps the circuit lineage ("" = none).
type SimLink struct {
	ID           string
	WorkspaceID  string
	AInterfaceID string
	ZInterfaceID string
	Status       EntityStatus
	Label        string
	ResourceID   string // "" = no lineage resource (SQL NULL)
	CreatedAt    time.Time
	UpdatedAt    time.Time
}

// ChangeSet is one recorded group of applied (or failed) operations on a
// workspace. Ids are globally monotonic (cs-<n>), so "latest changeset
// of a workspace" is the numerically largest id. RevertedAt zero means the
// changeset was not reverted.
type ChangeSet struct {
	ID          string
	WorkspaceID string
	Description string
	Trigger     ChangeSetTrigger
	Status      ChangeSetStatus
	OpsApplied  int
	CreatedAt   time.Time
	RevertedAt  time.Time // zero value = not reverted (SQL NULL)
}

// Reverted reports whether the changeset was undone (RevertedAt set).
func (cs ChangeSet) Reverted() bool {
	return !cs.RevertedAt.IsZero()
}

// ChangeSetOp is one operation row of a changeset, in application order
// (Seq is 1-based). OpJSON holds the typed forward op payload, InverseJSON
// the inverse op captured during application ("" = none: failed changesets
// never store inverses). Op codes are the constants prefixed "Op" in sim.go.
type ChangeSetOp struct {
	ChangeSetID string
	Seq         int
	OpCode      string
	OpJSON      string
	InverseJSON string // "" = no inverse (SQL NULL)
	OpResult    OpResult
}

// CheckRun is one execution of the deterministic simulation check catalog
// against a workspace state. ChangesetID is "" when the run was not triggered
// right after a changeset. TopologyJSON is the canonical edge snapshot of
// PROJECT_BRIEF_P2 §5 (same sort as the workspace state hash links array).
type CheckRun struct {
	ID           string
	WorkspaceID  string
	ChangesetID  string // "" = run not tied to a changeset (SQL NULL)
	Trigger      CheckTrigger
	RuleVersion  string
	StartedAt    time.Time
	DurationMs   int
	Score        int
	TopologyJSON string
}

// CheckResult is one row of a check run: a finding (Passed=false) or the
// per-check "ok" baseline row (Passed=true). CheckCode is one of the
// Check* constants; DetailJSON is the typed per-check detail. EntityKind is
// a free-form string in Phase 2 ("workspace" | "device" | "interface", ""
// = none) — deliberately NOT the Phase 1 EntityKind enum, whose values are
// "resource"/"relation".
type CheckResult struct {
	RunID      string
	Seq        int
	CheckCode  string
	Severity   Severity
	Passed     bool
	EntityKind string // "" = no entity (SQL NULL)
	EntityID   string // "" = no entity (SQL NULL)
	Message    string
	DetailJSON string
}

// Checkpoint is a snapshot marker of a workspace state: the Online-Backup
// copy of the database lives at FilePath (relative to the lab DB directory)
// and WorkspaceHash records the canonical state hash at creation time.
type Checkpoint struct {
	ID            string
	WorkspaceID   string
	Label         string
	FilePath      string
	WorkspaceHash string
	CreatedAt     time.Time
}
